// Braille block range used as the glyph set for reveal/glitch scrambling.
export const BRAILLE_GLYPHS = (() => {
  let s = "";
  for (let c = 0x2801; c < 0x2900; c++) s += String.fromCharCode(c);
  return s;
})();
